package dev.zomboid.remains.hygiene;
import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.world.effect.MobEffectInstance;import de.maxhenkel.corpse.entities.CorpseEntity;
public class HygieneChecks{
 static int checks;static void ok(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 public static class Tag{public Map<String,Long> data=new HashMap<>();public boolean contains(String k){return data.containsKey(k);}public void putLong(String k,long v){data.put(k,v);}public long getLong(String k){return data.getOrDefault(k,0L);}}
 public static class Food{public int level=20;public float saturation=5;public int getFoodLevel(){return level;}public float getSaturationLevel(){return saturation;}public void setFoodLevel(int v){level=v;}public void setSaturation(float v){saturation=v;}}
 public static class Box{public Object inflate(double d){return this;}}
 public static class Vector{public double x=1,z;}
 public static class Player{public World w;public double x=.5,y=64,z=.5;public boolean creative,spectator,alive=true;public Food food=new Food();public homeostatic.network.Water water=new homeostatic.network.Water();public MobEffectInstance effect;public Player(World w){this.w=w;}public double getX(){return x;}public double getY(){return y;}public double getZ(){return z;}public double getEyeY(){return y+1.6;}public World level(){return w;}public BlockPos blockPosition(){return new BlockPos((int)Math.floor(x),(int)y,(int)Math.floor(z));}public Object getBoundingBox(){return new Box();}public Object getLookAngle(){return new Vector();}public boolean isAlive(){return alive;}public boolean isCreative(){return creative;}public boolean isSpectator(){return spectator;}public Object getEffect(Object o){return effect;}public void removeEffect(Object o){effect=null;}public void addEffect(MobEffectInstance e){effect=e;}public Food getFoodData(){return food;}}
 public record BlockState(String block,boolean air){public Object getBlock(){return block;}public boolean isAir(){return air;}public boolean isFaceSturdy(Object w,Object p,Object direction){return !air;}}
 public static class Corpse{public String block="doomsday_decoration:remains_0";public long born=0;}
 public static class Data{public Map<Long,Corpse> corpses=new HashMap<>();public void setDirty(){}}
 public static class World{public long time;public Data data=new Data();public List<Player> players=new ArrayList<>();public List<CorpseEntity> entities=new ArrayList<>();public Map<BlockPos,BlockState> blocks=new HashMap<>();public int flyParticles,vomitParticles,sounds,placements,chunkCalls;public boolean loaded=true;public long getGameTime(){return time;}public List<Player> players(){return players;}public List<?> getEntitiesOfClass(Class<?> c,Object box){return entities;}public boolean hasChunkAt(Object p){chunkCalls++;return loaded;}public BlockState getBlockState(BlockPos p){return blocks.getOrDefault(p,p.y()<64?new BlockState("minecraft:stone",false):new BlockState("minecraft:air",true));}public boolean setBlock(BlockPos p,BlockState s,int flags){blocks.put(p,s);placements++;return true;}public void sendParticles(Object type,double x,double y,double z,int n,double a,double b,double c,double speed){if(type==HygieneContent.FLY)flyParticles+=n;else vomitParticles+=n;}public void playSound(Object who,Object pos,Object sound,Object channel,float volume,float pitch){sounds++;}}
 public static class Server{public World world;public Server(World w){world=w;}public int getTickCount(){return (int)world.time;}public Iterable<World> getAllLevels(){return List.of(world);}}
 public static class Event{public Server server;public Event(Server s){server=s;}public Object getServer(){return server;}}
 static long pack(int x,int y,int z){return ((long)x&0x3ffffffL)<<38|((long)z&0x3ffffffL)<<12|((long)y&0xfffL);}
 public static void main(String[]a)throws Exception{Exposure single=new Exposure();for(int tick=0;tick<=6000;tick+=20){Exposure.Result r=single.step(tick,1);ok(!r.nausea()&&!r.vomit(),"one corpse alone does not start sickness");}
 Exposure e=new Exposure();for(int tick=0;tick<1200;tick+=20)ok(!e.step(tick,2).nausea(),"no nausea before one minute");ok(e.step(1200,2).nausea(),"mild nausea starts at one minute");for(int tick=1220;tick<1800;tick+=20)ok(!e.step(tick,2).vomit(),"first vomit waits ninety seconds");ok(e.step(1800,2).vomit(),"first vomit at ninety seconds");for(int tick=1820;tick<3000;tick+=20)ok(!e.step(tick,1).vomit(),"one remaining body keeps exposure but cadence enforced");ok(e.step(3000,1).vomit(),"every minute until all bodies cleared");for(int tick=3020;tick<3220;tick+=20){Exposure.Result r=e.step(tick,0);ok(r.nausea()&&!r.vomit(),"clean grace retains nausea without vomiting");}ok(e.step(3220,0).clean()&&!e.engaged,"clean ten seconds resets state");
 for(String registry:List.of("block","particle","sound")){var event=new net.neoforged.neoforge.registries.RegisterEvent(registry);((java.util.function.Consumer<Object>)Class.forName("dev.zomboid.remains.hygiene.HygieneRegistry").getConstructor().newInstance()).accept(event);ok(event.entries.size()==1,"content registry entry "+registry);}ok(((net.minecraft.world.level.block.SnowLayerBlock)HygieneContent.VOMIT).properties.hardness==.05f&&!((net.minecraft.world.level.block.SnowLayerBlock)HygieneContent.VOMIT).properties.collision,"thin cleanable stain is soft and noncolliding");
 World w=new World();Player p=new Player(w);w.players.add(p);CorpseEntity c1=new CorpseEntity(1,64,0),c2=new CorpseEntity(2,64,0);w.entities.add(c1);w.entities.add(c2);Server server=new Server(w);Event event=new Event(server);
 for(int tick=0;tick<=1800;tick+=20){w.time=tick;Hygiene.server(event);if(tick<1200)ok(w.flyParticles==0,"fresh corpses no flies");if(tick==1200)ok(w.flyParticles>0&&p.effect!=null,"mature corpses emit flies and nausea starts");}
 ok(w.sounds==1&&p.food.level==16&&p.water.level==16,"one vomit loses exactly two food and water icons");ok(homeostatic.platform.Services.PLATFORM.syncs==1,"hydration synchronized once");ok(w.vomitParticles==16&&w.placements==1,"vomit particles and persistent green stain placed");
 w.entities.clear();for(int tick=1820;tick<=2020;tick+=20){w.time=tick;Hygiene.server(event);}ok(p.effect==null,"clean radius removes owned nausea in ten seconds");ok(w.sounds==1,"no extra vomit in clean grace");
 p.water.level=2;p.food.level=2;Hygiene.vomit(p);ok(p.water.level==0&&p.food.level==0,"loss clamps at zero");
 w.data.corpses.put(pack(1,64,1),new Corpse());w.blocks.put(new BlockPos(1,64,1),new BlockState("doomsday_decoration:remains_0",false));List<Hygiene.Body> bodies=Hygiene.nearby(p,w,2400);ok(bodies.size()==1&&bodies.getFirst().age()==2400,"tracked block corpse included with persisted age");w.blocks.remove(new BlockPos(1,64,1));ok(Hygiene.nearby(p,w,2400).isEmpty(),"already cleaned block is ignored before native map cleanup");
 c1.x=7;w.entities.add(c1);ok(Hygiene.nearby(p,w,2500).isEmpty(),"outside six block sphere ignored");p.creative=true;w.time=2600;Hygiene.server(event);ok(p.effect==null,"creative skips sickness");ok(toughasnails.api.thirst.ThirstHelper.calls==0,"Homeostatic prevents double charging TAN");homeostatic.common.attachments.WaterData.available=false;Hydration.drain(p);ok(toughasnails.api.thirst.ThirstHelper.calls==1&&toughasnails.api.thirst.ThirstHelper.THIRST.level==16,"TAN-only fallback loses four points once");System.out.println("HYGIENE_SERVER_POLICY_CHECKS="+checks);}}
